361:     private static void addNameToValues(Map<String, Object> recordMap, HashMap<String, Object> values) {
362:         String firstName = ifStringValueNull(recordMap.get("first_name"));
363:         String lastName = ifStringValueNull(recordMap.get("last_name"));
364:         String fullName = firstName + " " + lastName;
365: 
366:         values.put("name", List.of(Map.of("first_name", firstName, "last_name", lastName, "full_name", fullName)));
367:     }
