215:     private static List<Option<String>> getTargetRecordIdOptions(Context context, String targetObject) {
216: 
217:         Map<String, List<Object>> records = context.http(
218:             http -> http.post("/objects/%s/records/query".formatted(
219:                 targetObject)))
220:             .configuration(responseType(ResponseType.JSON))
221:             .execute()
222:             .getBody(new TypeReference<>() {});
223: 
224:         List<Option<String>> recordIdOptions = new ArrayList<>();
225: 
226:         for (Object record : records.get(DATA)) {
227:             if (record instanceof Map<?, ?> recordMap
228:                 && recordMap.get("id") instanceof Map<?, ?> recordId
229:                 && recordMap.get("values") instanceof Map<?, ?> recordValues) {
230: 
231:                 String recordName = "Unnamed person";
232: 
233:                 if (recordValues.get("name") instanceof List<?> recordValueNameList &&
234:                     !recordValueNameList.isEmpty() &&
235:                     recordValueNameList.getFirst() instanceof Map<?, ?> recordValueName) {
236:                     if (targetObject.equals("people")) {
237:                         recordName = (String) recordValueName.get("full_name");
238:                     } else {
239:                         recordName = (String) recordValueName.get("value");
240:                     }
241:                 }
242:                 recordIdOptions.add(option(recordName, (String) recordId.get("record_id")));
243:             }
244:         }
245: 
246:         return recordIdOptions;
247:     }
