296:     public static String subscribeWebhook(String eventType, Context context, String webhookUrl) {
297:         Map<String, Map<String, Object>> body = context.http(http -> http.post("/webhooks"))
298:             .body(
299:                 Body.of(
300:                     DATA, Map.of(
301:                         "target_url", webhookUrl,
302:                         "subscriptions", List.of(
303:                             Map.of("event_type", eventType,
304:                                 "filter", Map.of("$and", List.of()))))))
305:             .configuration(responseType(ResponseType.JSON))
306:             .execute()
307:             .getBody(new TypeReference<>() {});
308: 
309:         String webhookId = "";
310: 
311:         if (body.get(DATA)
312:             .get(ID) instanceof Map<?, ?> idMap) {
313:             webhookId = idMap.get("webhook_id")
314:                 .toString();
315:         }
316: 
317:         return webhookId;
318:     }
