49: /**
50:  * @author Arik Cohen
51:  * @author Ivica Cardic
52:  * @since Apr 24, 2017
53:  */
54: public class DefaultTaskCompletionHandler implements TaskCompletionHandler {
55: 
56:     private static final Logger logger = LoggerFactory.getLogger(DefaultTaskCompletionHandler.class);
57: 
58:     private static final Evaluator EVALUATOR = Evaluator.create();
59: 
60:     private final ApplicationEventPublisher eventPublisher;
61:     private final ContextService contextService;
62:     private final JobExecutor jobExecutor;
63:     private final JobService jobService;
64:     private final TaskExecutionService taskExecutionService;
65:     private final TaskFileStorage taskFileStorage;
66:     private final WorkflowService workflowService;
67: 
68:     @SuppressFBWarnings("EI")
69:     public DefaultTaskCompletionHandler(
70:         ContextService contextService, ApplicationEventPublisher eventPublisher, JobExecutor jobExecutor,
71:         JobService jobService, TaskExecutionService taskExecutionService, TaskFileStorage taskFileStorage,
72:         WorkflowService workflowService) {
73: 
74:         this.contextService = contextService;
75:         this.eventPublisher = eventPublisher;
76:         this.jobExecutor = jobExecutor;
77:         this.jobService = jobService;
78:         this.taskExecutionService = taskExecutionService;
79:         this.taskFileStorage = taskFileStorage;
80:         this.workflowService = workflowService;
81:     }
82: 
83:     @Override
84:     public boolean canHandle(TaskExecution taskExecution) {
85:         return taskExecution.getParentId() == null;
86:     }
87: 
88:     @Override
89:     public void handle(TaskExecution taskExecution) {
90:         Assert.notNull(taskExecution, "'taskExecution' must not be null");
91:         Assert.notNull(taskExecution.getId(), "'taskExecution.id' must not be null");
92: 
93:         if (logger.isTraceEnabled()) {
94:             logger.trace("handle: taskExecution={}", taskExecution);
95:         }
96: 
97:         Job job = jobService.getTaskExecutionJob(Validate.notNull(taskExecution.getId(), "id"));
98: 
99:         if (job == null) {
100:             logger.error("Unknown job id={}", taskExecution.getJobId());
101:         } else {
102:             taskExecution.setStatus(Status.COMPLETED);
103: 
104:             taskExecution = taskExecutionService.update(taskExecution);
105: 
106:             String name = taskExecution.getName();
107:             FileEntry output = taskExecution.getOutput();
108: 
109:             Map<String, Object> newContext = new HashMap<>(
110:                 taskFileStorage.readContextValue(
111:                     contextService.peek(Validate.notNull(job.getId(), "id"), Context.Classname.JOB)));
112: 
113:             if (name != null) {
114:                 if (output == null) {
115:                     newContext.put(name, null);
116:                 } else {
117:                     newContext.put(name, taskFileStorage.readTaskExecutionOutput(output));
118:                 }
119:             }
120: 
121:             long jobId = Objects.requireNonNull(job.getId());
122: 
123:             contextService.push(
124:                 jobId, Context.Classname.JOB,
125:                 taskFileStorage.storeContextValue(jobId, Context.Classname.JOB, newContext));
126: 
127:             logger.debug(
128:                 "Task id={}, type='{}', name='{}' completed", taskExecution.getId(), taskExecution.getType(), name);
129: 
130:             if (hasMoreTasks(job)) {
131:                 job.setCurrentTask(job.getCurrentTask() + 1);
132: 
133:                 job = jobService.update(job);
134: 
135:                 jobExecutor.execute(job);
136:             } else {
137:                 complete(job);
138:             }
139:         }
140:     }
141: 
142:     private void complete(Job job) {
143:         Assert.notNull(job, "'job' must not be null");
144: 
145:         if (logger.isTraceEnabled()) {
146:             logger.trace("complete: job={}", job);
147:         }
148: 
149:         Map<String, ?> context = taskFileStorage.readContextValue(
150:             contextService.peek(Validate.notNull(job.getId(), "id"), Context.Classname.JOB));
151:         Workflow workflow = workflowService.getWorkflow(job.getWorkflowId());
152: 
153:         Map<String, Object> source = MapUtils.toMap(
154:             workflow.getOutputs(), Workflow.Output::name, Workflow.Output::value);
155: 
156:         job.setCurrentTask(-1);
157:         job.setEndDate(Instant.now());
158:         job.setStatus(Job.Status.COMPLETED);
159:         job.setOutputs(
160:             taskFileStorage.storeJobOutputs(Validate.notNull(job.getId(), "id"), EVALUATOR.evaluate(source, context)));
161: 
162:         job = jobService.update(job);
163: 
164:         eventPublisher.publishEvent(
165:             new JobStatusApplicationEvent(Validate.notNull(job.getId(), "id"), job.getStatus()));
166: 
167:         if (logger.isDebugEnabled()) {
168:             logger.debug("Job id={}, label='{}' completed", job.getId(), job.getLabel());
169:         }
170:     }
171: 
172:     private boolean hasMoreTasks(Job job) {
173:         Workflow workflow = workflowService.getWorkflow(job.getWorkflowId());
174: 
175:         List<WorkflowTask> workflowTasks = workflow.getTasks();
176: 
177:         return job.getCurrentTask() + 1 < workflowTasks.size();
178:     }
179: }
