404:     private static AuthorizationCallbackFunction getDefaultAuthorizationCallbackFunction(
405:         ClientIdFunction clientIdFunction, ClientSecretFunction clientSecretFunction,
406:         TokenUrlFunction tokenUrlFunction) {
407: 
408:         return (connectionParameters, code, redirectUri, codeVerifier, context) -> {
409:             FormBodyPublisher.Builder builder = FormBodyPublisher.newBuilder();
410: 
411:             builder.query("client_id", clientIdFunction.apply(connectionParameters, context));
412:             builder.query("client_secret", clientSecretFunction.apply(connectionParameters, context));
413:             builder.query("code", code);
414:             builder.query("grant_type", "authorization_code");
415:             builder.query("redirect_uri", redirectUri);
416: 
417:             if (codeVerifier != null) {
418:                 builder.query("code_verifier", codeVerifier);
419:             }
420: 
421:             try (HttpClient httpClient = Methanol.newBuilder()
422:                 .version(HttpClient.Version.HTTP_1_1)
423:                 .build()) {
424: 
425:                 HttpResponse<String> httpResponse = httpClient.send(
426:                     HttpRequest.newBuilder()
427:                         .POST(builder.build())
428:                         .uri(URI.create(tokenUrlFunction.apply(connectionParameters, context)))
429:                         .header("Accept", "application/json")
430:                         .build(),
431:                     HttpResponse.BodyHandlers.ofString());
432: 
433:                 if (httpResponse.statusCode() < 200 || httpResponse.statusCode() > 299) {
434:                     throw new ConfigurationException(
435:                         "Invalid claim", ConnectionDefinitionErrorType.GET_DEFAULT_AUTHORIZATION_CALLBACK_FUNCTION);
436:                 }
437: 
438:                 if (httpResponse.body() == null) {
439:                     throw new ConfigurationException(
440:                         "Invalid claim", ConnectionDefinitionErrorType.GET_DEFAULT_AUTHORIZATION_CALLBACK_FUNCTION);
441:                 }
442: 
443:                 return new AuthorizationCallbackResponse(JsonUtils.read(httpResponse.body(), new TypeReference<>() {}));
444:             }
445:         };
446:     }
