349:     private boolean isProjectDeploymentWorkflowEnabled(ProjectWorkflow projectWorkflow, Environment environment) {
350:         // DRAFT status
351:         if (projectWorkflow.getProjectVersion() == 1) {
352:             return false;
353:         }
354: 
355:         projectWorkflow = projectWorkflowService
356:             .fetchProjectWorkflow(
357:                 projectWorkflow.getProjectId(), projectWorkflow.getProjectVersion() - 1,
358:                 projectWorkflow.getWorkflowReferenceCode())
359:             .orElse(null);
360: 
361:         if (projectWorkflow == null) {
362:             return false;
363:         }
364: 
365:         long projectDeploymentId = projectDeploymentService.getProjectDeploymentId(
366:             projectWorkflow.getProjectId(), environment);
367: 
368:         return projectDeploymentWorkflowService.isProjectDeploymentWorkflowEnabled(
369:             projectDeploymentId, projectWorkflow.getWorkflowId());
370:     }
