204:     public List<ConnectUserProjectWorkflowDTO> getProjectWorkflows(String externalUserId, Environment environment) {
205:         ConnectedUserProject connectedUserProject = checkConnectedUserProject(externalUserId, environment);
206: 
207:         Project project = projectService.getProject(connectedUserProject.getProjectId());
208: 
209:         List<ProjectWorkflow> latestProjectWorkflows = projectWorkflowService.getProjectWorkflows(
210:             project.getId(), project.getLastVersion());
211: 
212:         List<String> latestWorkflowIds = latestProjectWorkflows.stream()
213:             .map(ProjectWorkflow::getWorkflowId)
214:             .toList();
215: 
216:         return workflowService.getWorkflows(latestWorkflowIds)
217:             .stream()
218:             .map(workflow -> {
219:                 ProjectWorkflow latestProjectWorkflow = latestProjectWorkflows.stream()
220:                     .filter(curProjectWorkflow -> Objects.equals(curProjectWorkflow.getWorkflowId(), workflow.getId()))
221:                     .findFirst()
222:                     .orElseThrow();
223: 
224:                 ConnectedUserProjectWorkflow connectedUserProjectWorkflow = connectedUserProjectWorkflowService
225:                     .getConnectedUserProjectWorkflow(connectedUserProject.getId(), latestProjectWorkflow.getId());
226: 
227:                 return new ConnectUserProjectWorkflowDTO(
228:                     connectedUserProject.getConnectedUserId(),
229:                     isProjectDeploymentWorkflowEnabled(latestProjectWorkflow, environment), latestProjectWorkflow,
230:                     new WorkflowDTO(workflow, List.of(), List.of()), connectedUserProjectWorkflow.getWorkflowVersion());
231:             })
232:             .toList();
233:     }
